def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    rem = 100 - n
    if rem <= 1:
        return 'D'

    total_opp_c = 0
    wc = 0.0
    ws = 0.0
    denom = max(1, n - 1)

    for i in range(n):
        o = history[i][1]
        w = 1.0 + (i / denom) * 3.0
        ws += w
        if o == 'C':
            total_opp_c += 1
            wc += w

    if total_opp_c == 0:
        return 'D'

    p_global = wc / ws if ws > 0.0 else 0.5

    counts = {
        'CC': [0.0, 0.0],
        'CD': [0.0, 0.0],
        'DC': [0.0, 0.0],
        'DD': [0.0, 0.0]
    }

    trans = n - 1
    if trans > 0:
        tden = max(1, trans - 1)
        for j in range(trans):
            s = history[j][0] + history[j][1]
            nxt = 1.0 if history[j + 1][1] == 'C' else 0.0
            w = 1.0 + (j / tden) * 3.0
            counts[s][0] += nxt * w
            counts[s][1] += w

    alpha = 3.0
    q = {}
    for s in ('CC', 'CD', 'DC', 'DD'):
        cnt = counts[s]
        if s == 'CC':
            prior = p_global
        elif s == 'DC':
            prior = 0.02 + 0.10 * p_global
        elif s == 'CD':
            prior = 0.10 + 0.35 * p_global
        else:
            prior = 0.02 + 0.15 * p_global

        val = (cnt[0] + alpha * prior) / (cnt[1] + alpha)
        if val < 0.0:
            val = 0.0
        if val > 1.0:
            val = 1.0
        q[s] = val

    my_last, opp_last = history[-1]

    if total_opp_c == n and n >= 6:
        if my_last == 'C' or q['DC'] > 0.25:
            return 'D'

    streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
        else:
            break

    if opp_last == 'D':
        if total_opp_c * 3 <= n and streak_d >= 2:
            return 'D'

        if p_global < 0.25 and streak_d >= 3:
            return 'D'

        if my_last == 'C':
            unprovoked = True
            if n >= 2 and history[-2][0] == 'D':
                unprovoked = False

            if unprovoked:
                if q['CD'] < 0.72 or streak_d >= 2:
                    return 'D'
            else:
                if streak_d >= 4 and q['CD'] < 0.55:
                    return 'D'

        else:
            if total_opp_c * 4 <= n:
                return 'D'

            if total_opp_c > 0 and p_global > 0.60 and streak_d >= 2 and q['CD'] > 0.55:
                return 'C'

            if total_opp_c * 3 > n and p_global > 0.50 and rng.random() < 0.05:
                return 'C'

    state = my_last + opp_last
    pC = q[state]
    if pC < 0.0:
        pC = 0.0
    if pC > 1.0:
        pC = 1.0

    vc = 0.0
    vd = 0.0

    prob = pC
    if prob > 0.0:
        if rem == 2:
            futC = 1.0 + 4.0 * q['CC']
            futD = 1.0 + 4.0 * q['DC']
        else:
            factor = rem - 1.0
            futC = factor * (1.0 + 2.0 * q['CC'])
            futD = factor * (1.0 + 2.0 * q['DC'])

        vc += prob * (3.0 + futC)
        vd += prob * (5.0 + futD)

    prob = 1.0 - pC
    if prob > 0.0:
        if rem == 2:
            futC = 1.0 + 4.0 * q['CD']
            futD = 1.0 + 4.0 * q['DD']
        else:
            factor = rem - 1.0
            futC = factor * (1.0 + 2.0 * q['CD'])
            futD = factor * (1.0 + 2.0 * q['DD'])

        vc += prob * (0.0 + futC)
        vd += prob * (1.0 + futD)

    margin = 0.6 if rem <= 10 else 1.2
    if vd > vc + margin:
        return 'D'

    return 'C'
